module gold_scheduler (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] t0,\n    input wire [7:0] h0,\n    input wire [7:0] t1,\n    input wire [7:0] h1,\n    input wire [7:0] t2,\n    input wire [7:0] h2,\n    input wire [7:0] t3,\n    input wire [7:0] h3,\n    input wire [7:0] t4,\n    input wire [7:0] h4,\n    input wire [7:0] t5,\n    input wire [7:0] h5,\n    input wire [7:0] t6,\n    input wire [7:0] h6,\n    input wire [7:0] t7,\n    input wire [7:0] h7,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] LOAD       = 3'd1;\n    localparam [2:0] SORT       = 3'd2;\n    localparam [2:0] SELECT     = 3'd3;\n    localparam [2:0] FINISH     = 3'd4;\n\n    reg [2:0] state, next_state;\n    reg [7:0] t_reg [0:7];       // Task times\n    reg [7:0] h_reg [0:7];       // Altitude constraints\n    reg [7:0] sorted_t [0:7];\n    reg [7:0] sorted_h [0:7];\n    reg [7:0] selected_t [0:7];\n    reg [3:0] count;\n    reg [15:0] total_time;\n\n    // Bubble sort counters\n    reg [3:0] sort_i, sort_j;\n    // Selection iterator\n    reg [3:0] select_idx;\n\n    // Max value detector variables\n    reg [7:0] max_t;\n    reg [2:0] max_idx;\n    integer m;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all arrays and registers\n            result <= 4'd0;\n            done <= 1'b0;\n            count <= 4'd0;\n            total_time <= 16'd0;\n            state <= IDLE;\n            sort_i <= 4'd0;\n            sort_j <= 4'd0;\n            select_idx <= 4'd0;\n            for (integer i = 0; i < 8; i = i + 1) begin\n                t_reg[i] <= 8'd0;\n                h_reg[i] <= 8'd0;\n                sorted_t[i] <= 8'd0;\n                sorted_h[i] <= 8'd0;\n                selected_t[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                    end\n                end\n\n                LOAD: begin\n                    // Load inputs into registers\n                    t_reg[0] <= t0;\n                    h_reg[0] <= h0;\n                    t_reg[1] <= t1;\n                    h_reg[1] <= h1;\n                    t_reg[2] <= t2;\n                    h_reg[2] <= h2;\n                    t_reg[3] <= t3;\n                    h_reg[3] <= h3;\n                    t_reg[4] <= t4;\n                    h_reg[4] <= h4;\n                    t_reg[5] <= t5;\n                    h_reg[5] <= h5;\n                    t_reg[6] <= t6;\n                    h_reg[6] <= h6;\n                    t_reg[7] <= t7;\n                    h_reg[7] <= h7;\n                    state <= SORT;\n                    sort_i <= 4'd0;\n                    sort_j <= 4'd0;\n\n                    // Initialize sorted arrays\n                    for (integer i = 0; i < 8; i = i + 1) begin\n                        sorted_t[i] <= t_reg[i];\n                        sorted_h[i] <= h_reg[i];\n                    end\n                end\n\n                SORT: begin\n                    if (sort_i < 4'd7) begin\n                        if (sort_j < 4'd7 - sort_i) begin\n                            // Bubble sort comparison\n                            if (sorted_h[sort_j] > sorted_h[sort_j + 1]) begin\n                                // Swap elements\n                                sorted_t[sort_j] <= sorted_t[sort_j + 1];\n                                sorted_t[sort_j + 1] <= sorted_t[sort_j];\n                                sorted_h[sort_j] <= sorted_h[sort_j + 1];\n                                sorted_h[sort_j + 1] <= sorted_h[sort_j];\n                            end\n                            sort_j <= sort_j + 4'd1;\n                        end else begin\n                            sort_i <= sort_i + 4'd1;\n                            sort_j <= 4'd0;\n                        end\n                    end else begin\n                        // Sorting complete\n                        count <= 4'd0;\n                        total_time <= 16'd0;\n                        select_idx <= 4'd0;\n                        state <= SELECT;\n                        // Clear selected_t array\n                        for (integer i = 0; i < 8; i = i + 1) begin\n                            selected_t[i] <= 8'd0;\n                        end\n                    end\n                end\n\n                SELECT: begin\n                    if (select_idx < 4'd8) begin\n                        // Skip invalid entries (t=255, h=0)\n                        if (!(sorted_t[select_idx] == 8'd255 && sorted_h[select_idx] == 8'd0)) begin\n                            if (total_time + sorted_t[select_idx] <= sorted_h[select_idx]) begin\n                                // Add to selection\n                                selected_t[count] <= sorted_t[select_idx];\n                                total_time <= total_time + sorted_t[select_idx];\n                                count <= count + 4'd1;\n                            end else if (count > 4'd0) begin\n                                // Find max_t in selected_t array\n                                max_t = 8'd0;\n                                max_idx = 3'd0;\n                                for (m = 0; m < count; m = m + 1) begin\n                                    if (selected_t[m] > max_t) begin\n                                        max_t = selected_t[m];\n                                        max_idx = m[2:0];\n                                    end\n                                end\n\n                                // Replace only if new t is smaller\n                                if (sorted_t[select_idx] < max_t) begin\n                                    total_time <= total_time - max_t + sorted_t[select_idx];\n                                    selected_t[max_idx] <= sorted_t[select_idx];\n                                end\n                            end\n                        end\n                        select_idx <= select_idx + 4'd1;\n                    end else begin\n                        result <= count;\n                        state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule